<?php require __DIR__.'/includes/bootstrap.php';header('Content-Type: application/xml; charset=utf-8');$base=rtrim(APP_URL,'/');if(!$base){$base=((isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']==='on')?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost');}echo "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">";foreach(['/','/gadgets','/jersey','/fashion','/articles','/docs','/pages','/contact'] as $u)echo '<url><loc>'.htmlspecialchars($base.$u,ENT_XML1).'</loc></url>';foreach(db()->query("SELECT post_type,slug,updated_at FROM content_posts WHERE status='publish'")->fetchAll() as $r)echo '<url><loc>'.htmlspecialchars($base.content_url($r['post_type'],$r['slug']),ENT_XML1).'</loc><lastmod>'.htmlspecialchars(date('c',strtotime($r['updated_at'])),ENT_XML1).'</lastmod></url>';foreach(db()->query("SELECT slug FROM products WHERE status=1")->fetchAll() as $r)echo '<url><loc>'.htmlspecialchars($base.'/product.php?slug='.$r['slug'],ENT_XML1).'</loc></url>';echo '</urlset>';